PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?p / 100) AS ?m3) WHERE {
  { SELECT ?c (SUM(?o) AS ?oilC) WHERE {
      ?wp a :WellProduction ; :inConcession ?c ; :oil ?o .
    } GROUP BY ?c }
  { SELECT DISTINCT ?s ?c ?p WHERE {
      ?s a :Stake ; :inConcession ?c ; :partner ?e ; :percent ?p .
      ?e :name ?n .
      FILTER(STRSTARTS(UCASE(STR(?n)), "YPF"))
    } }
}
